INSERT INTO product_variant_types (product_id, name, display_order) SELECT id, 'Color de tapa', 1 FROM products WHERE sku = 'RD-002' AND NOT EXISTS (SELECT 1 FROM product_variant_types x JOIN products p2 ON p2.id = x.product_id WHERE p2.sku = 'RD-002' AND x.name = 'Color de tapa');

