INSERT INTO product_variant_types (product_id, name, display_order) SELECT id, 'Color', 1 FROM products WHERE sku = 'RD-046' AND NOT EXISTS (SELECT 1 FROM product_variant_types x JOIN products p2 ON p2.id = x.product_id WHERE p2.sku = 'RD-046' AND x.name = 'Color');

