INSERT INTO schools (name, address) SELECT v.name, v.address FROM (VALUES ('Colegio Los Álamos', 'Av. Ejército 410, Yanahuara'), ('I.E. Santa Rosa de Lima', 'Calle Mercaderes 220, Cercado'), ('Colegio Arco Iris', 'Av. Dolores 150, J. L. Bustamante y Rivero'), ('Colegio San Martín de Porres', 'Av. Lambramani 300, Arequipa')) AS v(name, address) WHERE NOT EXISTS (SELECT 1 FROM schools s WHERE s.name = v.name);

INSERT INTO school_sections (school_id, section_id) SELECT s.id, x.id FROM schools s CROSS JOIN sections x ON CONFLICT DO NOTHING;

INSERT INTO grades (school_id, name, year) SELECT (SELECT id FROM schools WHERE name = 'Colegio Los Álamos' LIMIT 1), '2do Primaria', 2027 WHERE NOT EXISTS (SELECT 1 FROM grades WHERE school_id = (SELECT id FROM schools WHERE name = 'Colegio Los Álamos' LIMIT 1) AND name = '2do Primaria' AND year = 2027);

