INSERT INTO supply_items (supply_list_id, nombre_original, nombre_detectado, cantidad, notas, matched_quantity,
  product_economico_id, price_economico, product_medio_id, price_medio, product_premium_id, price_premium, matched_product_id, price_at_match)
SELECT (SELECT id FROM supply_lists WHERE grade_id = (SELECT id FROM grades WHERE school_id = (SELECT id FROM schools WHERE name = 'Colegio Los Álamos' LIMIT 1) AND name = '2do Primaria' AND year = 2027 LIMIT 1) AND es_oficial LIMIT 1), v.texto, COALESCE(pm.name, pe.name, pp.name, v.texto), v.cant, v.notas, v.cant,
  pe.id, pe.base_price, pm.id, pm.base_price, pp.id, pp.base_price, COALESCE(pm.id, pe.id, pp.id), COALESCE(pm.base_price, pe.base_price, pp.base_price)
FROM (VALUES
  (0, '4 cuadernos A4 cuadriculados de 100 h.', 4, 'Forrados de azul', 'RD-001', 'RD-002', 'RD-003'),
  (1, '2 cuadernos A4 rayados', 2, NULL, 'RD-009', 'RD-010', 'RD-011'),
  (2, '1 caja de colores largos x24', 1, NULL, 'RD-013', 'RD-014', 'RD-015'),
  (3, '1 caja de crayones x12', 1, NULL, 'RD-016', 'RD-017', NULL),
  (4, '3 lápices 2B', 3, NULL, 'RD-026', 'RD-027', 'RD-028'),
  (5, '2 borradores blancos', 2, NULL, 'RD-034', 'RD-035', 'RD-036'),
  (6, '1 tajador con depósito', 1, NULL, 'RD-037', 'RD-038', 'RD-039'),
  (7, '1 tijera punta roma', 1, NULL, 'RD-040', 'RD-041', 'RD-042'),
  (8, '1 regla de 30 cm', 1, NULL, 'RD-043', 'RD-044', NULL),
  (9, '2 gomas en barra grandes', 2, NULL, 'RD-050', 'RD-051', 'RD-052'),
  (10, '1 paquete de papel lustre', 1, NULL, 'RD-055', 'RD-056', NULL),
  (11, '1 témperas de 7 colores', 1, NULL, 'RD-021', 'RD-022', 'RD-023'),
  (12, '1 plumón indeleble negro', 1, 'Marcado con el nombre', 'RD-031', 'RD-032', 'RD-033'),
  (13, '1 limpiatipo', 1, NULL, NULL, NULL, NULL)
) AS v(orden, texto, cant, notas, se, sm, sp)
LEFT JOIN products pe ON pe.sku = v.se LEFT JOIN products pm ON pm.sku = v.sm LEFT JOIN products pp ON pp.sku = v.sp
WHERE NOT EXISTS (SELECT 1 FROM supply_items WHERE supply_list_id = (SELECT id FROM supply_lists WHERE grade_id = (SELECT id FROM grades WHERE school_id = (SELECT id FROM schools WHERE name = 'Colegio Los Álamos' LIMIT 1) AND name = '2do Primaria' AND year = 2027 LIMIT 1) AND es_oficial LIMIT 1))
ORDER BY v.orden;

INSERT INTO grades (school_id, name, year) SELECT (SELECT id FROM schools WHERE name = 'Colegio Los Álamos' LIMIT 1), 'Inicial - 5 años', 2027 WHERE NOT EXISTS (SELECT 1 FROM grades WHERE school_id = (SELECT id FROM schools WHERE name = 'Colegio Los Álamos' LIMIT 1) AND name = 'Inicial - 5 años' AND year = 2027);

