INSERT INTO supply_items (supply_list_id, nombre_original, nombre_detectado, cantidad, notas, matched_quantity,
  product_economico_id, price_economico, product_medio_id, price_medio, product_premium_id, price_premium, matched_product_id, price_at_match)
SELECT (SELECT id FROM supply_lists WHERE grade_id = (SELECT id FROM grades WHERE school_id = (SELECT id FROM schools WHERE name = 'Colegio Los Álamos' LIMIT 1) AND name = 'Inicial - 5 años' AND year = 2027 LIMIT 1) AND es_oficial LIMIT 1), v.texto, COALESCE(pm.name, pe.name, pp.name, v.texto), v.cant, v.notas, v.cant,
  pe.id, pe.base_price, pm.id, pm.base_price, pp.id, pp.base_price, COALESCE(pm.id, pe.id, pp.id), COALESCE(pm.base_price, pe.base_price, pp.base_price)
FROM (VALUES
  (0, '1 caja de crayones jumbo', 1, NULL, 'RD-016', 'RD-017', NULL),
  (1, '2 cajas de plastilina', 2, NULL, 'RD-024', 'RD-025', NULL),
  (2, '1 témperas x7', 1, NULL, 'RD-021', 'RD-022', 'RD-023'),
  (3, '1 block de dibujo A4', 1, NULL, NULL, 'RD-059', 'RD-060'),
  (4, '1 paquete de cartulinas de colores', 1, NULL, 'RD-057', 'RD-058', NULL),
  (5, '1 cola sintética', 1, NULL, 'RD-053', 'RD-054', NULL),
  (6, '1 tijera punta roma', 1, NULL, 'RD-040', 'RD-041', 'RD-042'),
  (7, '1 folder con fastener', 1, NULL, 'RD-048', 'RD-049', NULL)
) AS v(orden, texto, cant, notas, se, sm, sp)
LEFT JOIN products pe ON pe.sku = v.se LEFT JOIN products pm ON pm.sku = v.sm LEFT JOIN products pp ON pp.sku = v.sp
WHERE NOT EXISTS (SELECT 1 FROM supply_items WHERE supply_list_id = (SELECT id FROM supply_lists WHERE grade_id = (SELECT id FROM grades WHERE school_id = (SELECT id FROM schools WHERE name = 'Colegio Los Álamos' LIMIT 1) AND name = 'Inicial - 5 años' AND year = 2027 LIMIT 1) AND es_oficial LIMIT 1))
ORDER BY v.orden;

INSERT INTO grades (school_id, name, year) SELECT (SELECT id FROM schools WHERE name = 'I.E. Santa Rosa de Lima' LIMIT 1), '3ro Primaria', 2027 WHERE NOT EXISTS (SELECT 1 FROM grades WHERE school_id = (SELECT id FROM schools WHERE name = 'I.E. Santa Rosa de Lima' LIMIT 1) AND name = '3ro Primaria' AND year = 2027);

