INSERT INTO supply_items (supply_list_id, nombre_original, nombre_detectado, cantidad, notas, matched_quantity,
  product_economico_id, price_economico, product_medio_id, price_medio, product_premium_id, price_premium, matched_product_id, price_at_match)
SELECT (SELECT id FROM supply_lists WHERE grade_id = (SELECT id FROM grades WHERE school_id = (SELECT id FROM schools WHERE name = 'Colegio Arco Iris' LIMIT 1) AND name = '1ro Secundaria' AND year = 2027 LIMIT 1) AND es_oficial LIMIT 1), v.texto, COALESCE(pm.name, pe.name, pp.name, v.texto), v.cant, v.notas, v.cant,
  pe.id, pe.base_price, pm.id, pm.base_price, pp.id, pp.base_price, COALESCE(pm.id, pe.id, pp.id), COALESCE(pm.base_price, pe.base_price, pp.base_price)
FROM (VALUES
  (0, '8 cuadernos A4 cuadriculados', 8, NULL, 'RD-001', 'RD-002', 'RD-003'),
  (1, '4 cuadernos A4 rayados', 4, NULL, 'RD-009', 'RD-010', 'RD-011'),
  (2, '3 lapiceros azules', 3, NULL, 'RD-029', 'RD-030', NULL),
  (3, '2 lápices 2B', 2, NULL, 'RD-026', 'RD-027', 'RD-028'),
  (4, '1 regla de 30 cm', 1, NULL, 'RD-043', 'RD-044', NULL),
  (5, '1 paquete papel bond A4', 1, NULL, 'RD-061', 'RD-062', NULL),
  (6, '1 cartuchera', 1, NULL, 'RD-045', 'RD-046', 'RD-047'),
  (7, '1 calculadora científica', 1, NULL, NULL, NULL, NULL)
) AS v(orden, texto, cant, notas, se, sm, sp)
LEFT JOIN products pe ON pe.sku = v.se LEFT JOIN products pm ON pm.sku = v.sm LEFT JOIN products pp ON pp.sku = v.sp
WHERE NOT EXISTS (SELECT 1 FROM supply_items WHERE supply_list_id = (SELECT id FROM supply_lists WHERE grade_id = (SELECT id FROM grades WHERE school_id = (SELECT id FROM schools WHERE name = 'Colegio Arco Iris' LIMIT 1) AND name = '1ro Secundaria' AND year = 2027 LIMIT 1) AND es_oficial LIMIT 1))
ORDER BY v.orden;

